function condIssue(m,c,where){if(!c?.type)return where+'：条件を選んでください';const t=c.type,w=m.map?.width,h=m.map?.height;
 if(['any','all'].includes(t)){if(!(c.conds||[]).length)return where+'：「'+(t==='all'?'かつ':'または')+'」の条件を足してください';for(const [i,x] of c.conds.entries()){const e=condIssue(m,x,where+'の条件'+(i+1));if(e)return e;}return null;}
 if(t==='unit_defeated'&&!find('units',c.unitId))return where+'：ユニットを選んでください';if(t==='capture_all'&&!c.tag&&!terrainOf(c.key)?.facility)return where+'：施設の目印か種類を選んでください';if(t==='reach'&&(c.unitIds||[]).some(id=>!find('units',id)))return where+'：到達するユニットが見つかりません';if(t==='units_out'){if(!(c.unitIds||[]).length)return where+'：撤退するユニットを選んでください';if(c.unitIds.some(id=>!find('units',id)))return where+'：撤退するユニットが見つかりません';if(c.exit===false&&!Number.isFinite(c.x))return where+'：撤退エリアを決めるか、撤退口からの撤退を数えてください';}
 if(['boss','squad_down'].includes(t)&&!squadsOf(m).some(g=>g.id===c.groupId))return where+'：部隊を選んでください';
 if(['reach','enemy_reach'].includes(t)&&!(c.x>=0&&c.y>=0&&c.x<w&&c.y<h))return where+'：マスがマップの外です';if(['capture','captured','facility_lost'].includes(t)&&!facFns(facilityAt(m,c.x,c.y)).length)return where+'：施設のマスを指定してください';
 if(['turn','defend','turn_limit','within'].includes(t)&&!(c.turns>=1))return where+'：ターン数を入れてください';
 if(t==='flag'&&!c.flag)return where+'：フラグ名を入れてください';if(t==='game_flag'&&!find('flags',c.flagId))return where+'：ゲームのフラグを選んでください';if(t==='var'&&!find('vars',c.varId))return where+'：変数を選んでください';if(t==='tension'&&!squadsOf(m).some(g=>g.id===c.groupId))return where+'：気力を見る部隊を選んでください';if(t==='game_cond'&&!(c.conds?.list||[]).length)return where+'：条件を入れてください';if(['objective_done','objective_failed'].includes(t)&&!(m.objectives||[]).some(o=>o.id===c.objectiveId))return where+'：作戦内ミッションを選んでください';if(t==='unit_down'&&!find('units',c.unitId))return where+'：ユニットを選んでください';return null;}

