function actText(m,a){switch(a.type){case 'talk':return '会話 '+(a.lines||[]).length+'行'+(a.lines?.[0]?'「'+(a.lines[0].speaker?a.lines[0].speaker+'：':'')+a.lines[0].text.slice(0,12)+'…」':'');case 'choice':return '選択肢 '+(a.options||[]).map(o=>o.label).join('／');case 'flag':return 'フラグ「'+(a.flag||'?')+'」';case 'spawn':return '増援：'+groupName(m,a.groupId);case 'withdraw':return '撤退：'+groupName(m,a.groupId);case 'tension':return '気力：'+groupName(m,a.groupId)+(a.op==='set'?'を'+(a.value??0)+'に':a.op==='sub'?' −'+(a.value??0):' +'+(a.value??0));case 'var':return '変数「'+(find('vars',a.varId)?.name||a.varId||'?')+'」'+(a.op==='set'?'を'+(a.value??0)+'に':a.op==='sub'?' −'+(a.value??0):' +'+(a.value??0));case 'side':return '陣営変更：'+groupName(m,a.groupId)+'→'+(FACTIONS_TO[a.to||'enemy']||a.to);
 case 'area_show':return '「'+(areaName(m,a.target)||'?')+'」を'+(a.game===false?'隠す':'表示する');case 'exit_area':return '撤退エリアを'+(a.on===false?'閉じる ':'開く ')+at(a)+' '+(a.w||1)+'×'+(a.h||1);case 'map_expand':return 'マップを広げる '+at(a)+' '+(a.w||1)+'×'+(a.h||1);case 'terrain':return '地形：'+(terrainOf(a.key)?.name||'⚠'+a.key)+' '+at(a)+' '+(a.w||1)+'×'+(a.h||1);case 'victory':case 'defeat':return (a.type==='victory'?'勝利':'敗北')+'条件→'+(a.keep?'（条件はそのまま）':ctext(m,a.cond))+(a.text?' 表示「'+a.text+'」':'');case 'objective_change':return '「'+obName(m,a.id)+'」→'+[a.success?'成功:'+ctext(m,a.success):'',a.fail?'失敗:'+ctext(m,a.fail):'',a.text?'表示「'+a.text+'」':'',a.failText?'失敗の表示「'+a.failText+'」':''].filter(Boolean).join(' ')||'変更なし';case 'objective':return '「'+obName(m,a.id)+'」'+({start:'を発生',failed:'を失敗'}[a.result]||'を達成');case 'game_flag':return 'ゲームのフラグ「'+(find('flags',a.flagId)?.name||a.flagId||'?')+'」を'+(a.value===false?'OFF':'ON');case 'resupply':return '補給 '+(a.scope==='group'?groupName(m,a.groupId):a.scope==='area'?at(a)+'〜'+(a.w||1)+'×'+(a.h||1):OWNERS[a.faction||'player']+'全体')+' '+(a.pct||100)+'%';case 'ai':return 'AI：'+groupName(m,a.groupId)+'→'+(a.rules?'ルール'+a.rules.length+'件・':'')+(AI[a.pattern]||'そのまま')+(a.target?'・'+TARGET[a.target]:'');default:return ACTS[a.type]||a.type;}}
