/* ---------- star conditions ---------- */
const STAR={clear:'勝利',no_loss:'撃破された味方なし',turns_le:'○ターン以内に勝利',hp_ge:'残りHP合計が○%以上'},STD_STARS=[{type:'clear'},{type:'no_loss'},{type:'turns_le',value:10}];
